{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Neuron Growth</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #05070f;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    overflow: hidden;
    font-family: monospace;
  }
  canvas {
    border: 1px solid rgba(0, 229, 255, 0.15);
    box-shadow: 0 0 60px rgba(0, 229, 255, 0.1), 0 0 120px rgba(16, 26, 58, 0.4);
    border-radius: 2px;
  }
</style>
</head>
<body>
<canvas id="c" width="800" height="800"></canvas>
<script src="https://cdn.jsdelivr.net/npm/dat.gui@0.7.9/build/dat.gui.min.js"></script>
<script>
// ============================================================
// Setup
// ============================================================
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const W = canvas.width;
const H = canvas.height;

// Color palette
const PALETTE = {
  bg: '#05070f',
  bgGlow: '#101a3a',
  branch: '#00e5ff',
  accentBranch: '#d6ff00',
  synapse: '#ff2bd6',
  pulse: '#fff36a',
  ui: '#ffd400',
  scanline: 'rgba(0, 229, 255, 0.08)'
};

// ============================================================
// State
// ============================================================
let params = {
  neuronCount: 5,
  growthSpeed: 0.6,
  maxBranchDepth: 7,
  branchSplitChance: 0.18,
  branchCurvature: 0.4,
  maxBranchLength: 120,
  synapseDistance: 28,
  synapseGlow: 14,
  pulseSpeed: 3.2,
  pulseFrequency: 0.035,
  pulseBrightness: 1.0,
  bgColor: PALETTE.bg,
  branchColor: PALETTE.branch,
  accentBranchColor: PALETTE.accentBranch,
  synapseColor: PALETTE.synapse,
  pulseColor: PALETTE.pulse
};

let neurons = [];
let branches = [];
let synapses = [];
let pulses = [];
let growing = true;
let paused = false;
let frame = 0;
let animId = null;

// ============================================================
// Neuron class
// ============================================================
class Neuron {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.branches = [];
    this.id = Math.random().toString(36).slice(2, 8);
  }
}

// ============================================================
// Branch class
// ============================================================
class Branch {
  constructor(parent, startX, startY, angle, depth, thickness, isAccent) {
    this.parent = parent;
    this.startX = startX;
    this.startY = startY;
    this.angle = angle;
    this.depth = depth;
    this.thickness = thickness;
    this.isAccent = isAccent;
    this.segments = [];
    this.tipX = startX;
    this.tipY = startY;
    this.length = 0;
    this.alive = true;
    this.ctrlOffset = (Math.random() - 0.5) * 60 * params.branchCurvature;
  }

  grow() {
    if (!this.alive) return;
    const step = params.growthSpeed * (0.8 + Math.random() * 0.4);
    const newAngle = this.angle + (Math.random() - 0.5) * 0.35 * params.branchCurvature;
    const dx = Math.cos(newAngle) * step;
    const dy = Math.sin(newAngle) * step;
    const ex = this.tipX + dx;
    const ey = this.tipY + dy;
    this.segments.push({ x: this.tipX, y: this.tipY });
    this.tipX = ex;
    this.tipY = ey;
    this.length += step;
    this.ctrlOffset += (Math.random() - 0.5) * 8;

    if (this.length >= params.maxBranchLength || this.depth >= params.maxBranchDepth) {
      this.alive = false;
    }
  }

  // Get control point for quadratic curve
  getControlPoint() {
    const idx = this.segments.length - 1;
    if (idx < 1) return null;
    const prev = this.segments[idx - 1];
    const curr = this.segments[idx];
    const cpx = (prev.x + curr.x) / 2 + this.ctrlOffset * 0.3;
    const cpy = (prev.y + curr.y) / 2 + this.ctrlOffset * 0.2;
    return { x: cpx, y: cpy };
  }
}

// ============================================================
// Pulse class
// ============================================================
class Pulse {
  constructor(branchA, branchB, color) {
    this.branchA = branchA;
    this.branchB = branchB;
    this.color = color;
    this.t = Math.random();
    this.speed = params.pulseSpeed * (0.7 + Math.random() * 0.6);
    this.alive = true;
    this.size = 3 + Math.random() * 4;
  }

  update() {
    this.t += 0.016 * this.speed;
    if (this.t >= 1) {
      this.alive = false;
    }
  }

  getPosition() {
    const a = this.branchA;
    const b = this.branchB;
    const t = this.t;
    // Interpolate along the combined path of both branches
    const segsA = a.segments;
    const segsB = b.segments;
    const totalLenA = a.length || 1;
    const totalLenB = b.length || 1;
    const posA = this.lerpSegments(segsA, t * 0.5, totalLenA);
    const posB = this.lerpSegments(segsB, 1 - (1 - t) * 0.5, totalLenB);
    return {
      x: posA.x + (posB.x - posA.x) * t,
      y: posA.y + (posB.y - posA.y) * t
    };
  }

  lerpSegments(segs, t, totalLen) {
    if (!segs || segs.length < 2) return { x: 0, y: 0 };
    let accumulated = 0;
    const target = t * totalLen;
    for (let i = 1; i < segs.length; i++) {
      const dx = segs[i].x - segs[i-1].x;
      const dy = segs[i].y - segs[i-1].y;
      const segLen = Math.sqrt(dx*dx + dy*dy);
      if (accumulated + segLen >= target) {
        const frac = (target - accumulated) / (segLen || 1);
        return {
          x: segs[i-1].x + dx * frac,
          y: segs[i-1].y + dy * frac
        };
      }
      accumulated += segLen;
    }
    return segs[segs.length - 1];
  }
}

// ============================================================
// Network generation
// ============================================================
function regenerateNetwork() {
  neurons = [];
  branches = [];
  synapses = [];
  pulses = [];
  growing = true;

  const count = Math.floor(params.neuronCount);
  const cx = W / 2;
  const cy = H / 2;

  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2 + (Math.random() - 0.5) * 0.8;
    const dist = 30 + Math.random() * 50;
    const nx = cx + Math.cos(angle) * dist;
    const ny = cy + Math.sin(angle) * dist;
    const neuron = new Neuron(nx, ny);
    neurons.push(neuron);

    // Initial branches from seed neuron
    const numInit = 2 + Math.floor(Math.random() * 2);
    for (let j = 0; j < numInit; j++) {
      const a = (j / numInit) * Math.PI * 2 + (Math.random() - 0.5) * 0.6;
      const thick = 1.2 + Math.random() * 1.2;
      const accent = Math.random() < 0.3;
      const branch = new Branch(neuron, nx, ny, a, 0, thick, accent);
      neuron.branches.push(branch);
      branches.push(branch);
    }
  }
}

// ============================================================
// Growth step
// ============================================================
function growStep() {
  if (!growing) return;
  let grew = false;
  const toSplit = [];

  for (const branch of branches) {
    if (!branch.alive) continue;
    branch.grow();
    grew = true;

    // Split into side branch
    if (branch.depth < params.maxBranchDepth &&
        Math.random() < params.branchSplitChance * 0.15 &&
        branch.length > 20) {
      toSplit.push(branch);
    }
  }

  for (const parent of toSplit) {
    if (parent.depth >= params.maxBranchDepth - 1) continue;
    const childAngle = parent.angle + (Math.random() - 0.5) * 1.2;
    const childThick = parent.thickness * (0.4 + Math.random() * 0.3);
    const child = new Branch(
      parent.parent,
      parent.tipX,
      parent.tipY,
      childAngle,
      parent.depth + 1,
      childThick,
      Math.random() < 0.35
    );
    parent.parent.branches.push(child);
    branches.push(child);
  }

  // Stop growing when stable size reached
  if (branches.length > 350 || frame > 1200) {
    growing = false;
  }
}

// ============================================================
// Synapse detection
// ============================================================
function detectSynapses() {
  const threshold = params.synapseDistance;
  const toAdd = [];

  for (let i = 0; i < branches.length; i++) {
    const a = branches[i];
    if (!a.alive && a.segments.length < 2) continue;
    for (let j = i + 1; j < branches.length; j++) {
      const b = branches[j];
      if (!b.alive && b.segments.length < 2) continue;

      // Check if already connected
      let dup = false;
      for (const s of synapses) {
        if ((s.branchA === a && s.branchB === b) || (s.branchA === b && s.branchB === a)) {
          dup = true;
          break;
        }
      }
      if (dup) continue;

      const tipA = { x: a.tipX, y: a.tipY };
      const tipB = { x: b.tipX, y: b.tipY };
      const dx = tipA.x - tipB.x;
      const dy = tipA.y - tipB.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < threshold) {
        toAdd.push({ a, b });
      }
    }
  }

  for (const { a, b } of toAdd) {
    synapses.push({
      branchA: a,
      branchB: b,
      glowPhase: Math.random() * Math.PI * 2,
      createdAt: frame
    });
  }
}

// ============================================================
// Pulse spawning
// ============================================================
function spawnPulses() {
  if (synapses.length === 0) return;
  if (Math.random() < params.pulseFrequency) {
    const idx = Math.floor(Math.random() * synapses.length);
    const syn = synapses[idx];
    const color = Math.random() < 0.3 ? params.accentBranchColor : params.pulseColor;
    pulses.push(new Pulse(syn.branchA, syn.branchB, color));
  }
}

// ============================================================
// Rendering
// ============================================================
function hexToRgb(hex) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return { r, g, b };
}

function drawBackground() {
  ctx.fillStyle = params.bgColor;
  ctx.fillRect(0, 0, W, H);

  // Subtle radial glow
  const grad = ctx.createRadialGradient(W/2, H/2, 50, W/2, H/2, 450);
  const rgb = hexToRgb(PALETTE.bgGlow);
  grad.addColorStop(0, `rgba(${rgb.r},${rgb.g},${rgb.b},0.12)`);
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawGrid() {
  ctx.strokeStyle = PALETTE.scanline;
  ctx.lineWidth = 0.5;
  const step = 40;
  for (let x = 0; x <= W; x += step) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
    ctx.stroke();
  }
  for (let y = 0; y <= H; y += step) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }
}

function drawScanlines() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.04)';
  for (let y = 0; y < H; y += 3) {
    ctx.fillRect(0, y, W, 1);
  }
}

function drawVignette() {
  const grad = ctx.createRadialGradient(W/2, H/2, 200, W/2, H/2, 500);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawBranch(branch) {
  if (branch.segments.length < 2) return;
  const color = branch.isAccent ? params.accentBranchColor : params.branchColor;
  const rgb = hexToRgb(color);
  const thickness = branch.thickness;

  ctx.lineWidth = thickness;
  ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.85)`;
  ctx.shadowColor = color;
  ctx.shadowBlur = branch.isAccent ? 8 : 5;

  ctx.beginPath();
  const segs = branch.segments;
  ctx.moveTo(segs[0].x, segs[0].y);

  for (let i = 1; i < segs.length; i++) {
    const cp = branch.getControlPoint();
    if (cp && i === segs.length - 1) {
      ctx.quadraticCurveTo(cp.x, cp.y, segs[i].x, segs[i].y);
    } else {
      ctx.lineTo(segs[i].x, segs[i].y);
    }
  }
  ctx.stroke();
}

function drawSynapse(syn) {
  const a = syn.branchA;
  const b = syn.branchB;
  const tipA = { x: a.tipX, y: a.tipY };
  const tipB = { x: b.tipX, y: b.tipY };

  const phase = syn.glowPhase + frame * 0.02;
  const pulse = Math.sin(phase) * 0.5 + 0.5;
  const glow = params.synapseGlow * (0.6 + pulse * 0.4);
  const color = params.synapseColor;
  const rgb = hexToRgb(color);

  // Glow line between tips
  ctx.lineWidth = 1.5 + pulse * 1.5;
  ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${0.4 + pulse * 0.4})`;
  ctx.shadowColor = color;
  ctx.shadowBlur = glow;
  ctx.beginPath();
  ctx.moveTo(tipA.x, tipA.y);
  ctx.lineTo(tipB.x, tipB.y);
  ctx.stroke();

  // Glowing nodes at connection points
  ctx.shadowBlur = glow * 1.5;
  ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${0.6 + pulse * 0.4})`;
  ctx.beginPath();
  ctx.arc(tipA.x, tipA.y, 2 + pulse * 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(tipB.x, tipB.y, 2 + pulse * 2, 0, Math.PI * 2);
  ctx.fill();
}

function drawPulse(pulse) {
  const pos = pulse.getPosition();
  const color = pulse.color;
  const rgb = hexToRgb(color);
  const bright = params.pulseBrightness;
  const size = pulse.size * (1 + Math.sin(frame * 0.3 + pulse.t * 10) * 0.3);

  // Outer glow
  ctx.shadowColor = color;
  ctx.shadowBlur = 20 * bright;
  ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${0.9 * bright})`;
  ctx.beginPath();
  ctx.arc(pos.x, pos.y, size * 1.5, 0, Math.PI * 2);
  ctx.fill();

  // Core
  ctx.shadowBlur = 12 * bright;
  ctx.fillStyle = `rgba(255,255,255,${0.95 * bright})`;
  ctx.beginPath();
  ctx.arc(pos.x, pos.y, size * 0.6, 0, Math.PI * 2);
  ctx.fill();
}

function render() {
  drawBackground();
  drawGrid();

  // Draw branches
  for (const branch of branches) {
    drawBranch(branch);
  }

  // Draw synapses
  ctx.shadowBlur = 0;
  for (const syn of synapses) {
    drawSynapse(syn);
  }

  // Draw pulses
  for (const pulse of pulses) {
    drawPulse(pulse);
  }

  drawScanlines();
  drawVignette();

  // Reset shadow
  ctx.shadowBlur = 0;
}

// ============================================================
// Animation loop
// ============================================================
function animate() {
  frame++;

  if (!paused) {
    growStep();
    detectSynapses();
    spawnPulses();

    // Update pulses
    for (let i = pulses.length - 1; i >= 0; i--) {
      pulses[i].update();
      if (!pulses[i].alive) {
        pulses.splice(i, 1);
      }
    }

    // Cap pulses
    if (pulses.length > 60) {
      pulses.splice(0, pulses.length - 60);
    }
  }

  render();
  animId = requestAnimationFrame(animate);
}

// ============================================================
// GUI Setup
// ============================================================
function setupGUI() {
  const gui = new dat.GUI({ width: 300 });

  const growthFolder = gui.addFolder('Growth');
  growthFolder.add(params, 'neuronCount', 3, 8, 1).name('Neuron Count').onChange(regenerateNetwork);
  growthFolder.add(params, 'growthSpeed', 0.1, 2.0, 0.05).name('Growth Speed');
  growthFolder.add(params, 'maxBranchDepth', 3, 12, 1).name('Max Branch Depth');
  growthFolder.add(params, 'branchSplitChance', 0.02, 0.5, 0.01).name('Split Chance');
  growthFolder.add(params, 'branchCurvature', 0.1, 1.0, 0.05).name('Curvature');
  growthFolder.add(params, 'maxBranchLength', 40, 250, 5).name('Max Branch Length');
  growthFolder.open();

  const synFolder = gui.addFolder('Synapses');
  synFolder.add(params, 'synapseDistance', 10, 60, 1).name('Distance Threshold');
  synFolder.add(params, 'synapseGlow', 4, 30, 1).name('Glow Strength');
  synFolder.open();

  const pulseFolder = gui.addFolder('Pulses');
  pulseFolder.add(params, 'pulseSpeed', 0.5, 8.0, 0.1).name('Speed');
  pulseFolder.add(params, 'pulseFrequency', 0.005, 0.1, 0.001).name('Frequency');
  pulseFolder.add(params, 'pulseBrightness', 0.2, 2.0, 0.05).name('Brightness');
  pulseFolder.open();

  const visFolder = gui.addFolder('Visuals');
  visFolder.addColor(params, 'bgColor').name('Background');
  visFolder.addColor(params, 'branchColor').name('Branch Color');
  visFolder.addColor(params, 'accentBranchColor').name('Accent Color');
  visFolder.addColor(params, 'synapseColor').name('Synapse Color');
  visFolder.addColor(params, 'pulseColor').name('Pulse Color');
  visFolder.open();

  // Buttons
  gui.add({ regenerate: regenerateNetwork }, 'regenerate').name('Regenerate Network');
  gui.add({ clear: clearCanvas }, 'clear').name('Clear Canvas');
  gui.add({ toggle: togglePause }, 'toggle').name(paused ? 'Resume' : 'Pause');

  return gui;
}

function clearCanvas() {
  neurons = [];
  branches = [];
  synapses = [];
  pulses = [];
  growing = false;
  frame = 0;
}

function togglePause() {
  paused = !paused;
}

// ============================================================
// Start
// ============================================================
regenerateNetwork();
setupGUI();
animate();
</script>
</body>
</html>
